import java.io.*;
import java.math.*;
import java.util.*;

public class Main {
    static final BigInteger MOD = BigInteger.valueOf(998244353L);
    static final long MODL = 998244353L;
    static final long INV2 = 499122177L;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        Scanner sc = new Scanner(br);
        PrintWriter out = new PrintWriter(System.out);
        long n = sc.nextInt();
        long m = sc.nextInt();
        long l = sc.nextInt();
        long r = sc.nextInt();
        long cells = n * m;
        String ans = solve(l, r, cells);
        if (cells % 2 == 1) {
            out.print(ans);
        } else {
            out.println(ans);
        }
        out.flush();
        sc.close();
        br.close();
    }

    static String solve(long l, long r, long cells) {
        long k = r - l;
        long even = k / 2 + 1;
        long odd = (k + 1) / 2;
        if (cells % 2 == 1) {
            return BigInteger.valueOf(k + 1).modPow(BigInteger.valueOf(cells), MOD).toString();
        }
        BigInteger temp1 = BigInteger.valueOf(even + odd).modPow(BigInteger.valueOf(cells), MOD);
        BigInteger temp2 = BigInteger.valueOf(even - odd).modPow(BigInteger.valueOf(cells), MOD);
        long sum = (temp1.longValue() + temp2.longValue()) % MODL;
        long ans = sum * INV2 % MODL;
        return String.valueOf(ans);
    }
}
